redirects = {"old-a": "mid", "mid": "new-a", "loop1": "loop2", "loop2": "loop1"}
def follow(start, cap=10):
    seen, cur = [], start
    while cur in redirects and len(seen) < cap:
        if cur in seen: return None, "loop"
        seen.append(cur); cur = redirects[cur]
    return cur, "ok" if len(seen) < cap else "too-long"
print(follow("old-a"), follow("loop1"))
assert follow("old-a") == ("new-a", "ok") and follow("loop1")[1] == "loop"

graph = {"a": ["b"], "b": ["c"], "c": [], "d": ["a"]}
def reachable(start):
    seen, stack = set(), [start]
    while stack:
        n = stack.pop()
        for m in graph[n]:
            if m not in seen: seen.add(m); stack.append(m)
    return seen
print("reachable from d:", reachable("d"))
assert reachable("d") == {"a", "b", "c"}

outlinks = {"a": ["b", "c"], "b": ["c"], "c": []}
inlinks = {n: [] for n in outlinks}
for src, tgts in outlinks.items():
    for t in tgts: inlinks[t].append(src)
print("cited by c:", inlinks["c"])
assert inlinks["c"] == ["a", "b"]

def toks(s): return set(s.lower().replace(",", "").replace(".", "").split())
def sim(a, b):
    ta, tb = toks(a), toks(b)
    return len(ta & tb) / len(ta | tb)
a, b = "Higgins J 2026 Archive Intelligence", "Higgins J. 2026 Archive intelligence"
print("similarity:", round(sim(a, b), 2))
assert sim(a, b) > 0.8

import hashlib
def canonical_id(key):
    return "JAH-REF-" + hashlib.md5(key.encode()).hexdigest()[:8].upper()
cid = canonical_id("higgins-2026-archive-intelligence")
print("canonical:", cid)
assert canonical_id("higgins-2026-archive-intelligence") == cid

versions = {"doc-1": ["v1", "v2", "v3"]}
def resolve(base, pin=None):
    vs = versions[base]
    return pin if pin in vs else vs[-1]
print(resolve("doc-1"), resolve("doc-1", "v1"))
assert (resolve("doc-1"), resolve("doc-1", "v1")) == ("v3", "v1")

aliases = {"old-name": "doc-1", "older-name": "doc-1"}
primary = {"doc-1": "current record"}
def resolve(name):
    name = aliases.get(name, name)
    return primary.get(name)
print(resolve("older-name"))
assert resolve("older-name") == "current record"
